<?php
 namespace Pterodactyl\Models\Dezerx; use Pterodactyl\Models\Model; use Pterodactyl\Models\Server; use Illuminate\Database\Eloquent\Relations\HasMany; use Illuminate\Database\Eloquent\Relations\BelongsTo; class RustWipe extends Model { public const RESOURCE_NAME = 'rust_wipe'; protected $table = 'dezerx_rust_wipes'; protected $guarded = ['id']; protected $casts = [ 'server_id' => 'int', 'enabled' => 'bool', 'weekday' => 'int', 'config' => 'array', 'next_run_at' => 'int', 'last_run_at' => 'int', 'created_by' => 'int', ]; public static array $validationRules = [ 'server_id' => 'required|int|exists:servers,id', 'name' => 'required|string|max:64', 'frequency' => 'required|string|in:once,weekly,biweekly,monthly', 'weekday' => 'nullable|int|between:0,6', 'starts_on' => 'nullable|date_format:Y-m-d', 'at_time' => 'required|string|date_format:H:i', 'timezone' => 'required|string|timezone:all_with_bc', ]; public function server(): BelongsTo { return $this->belongsTo(Server::class); } public function runs(): HasMany { return $this->hasMany(RustWipeRun::class, 'wipe_id'); } } 